{"claims": [
  {
    "claim": "JH69U1 无法清洗拖布时，与水箱相关的检查处理步骤如下",
    "verdict": "unsupported",
    "evidence_index": null,
    "reason": "片段未将'无法清洗拖布'这一故障情形与水箱检查步骤明确关联"
  },
  {
    "claim": "取出清水箱，检查水量是否充足；若清水箱已空，需及时添加市政自来水至最高水位线以下",
    "verdict": "supported",
    "evidence_index": [2, 5],
    "reason": "[2]记载加水至最高水位线以下，[5]记载检查并补充清水箱水量"
  },
  {
    "claim": "取出清水箱中的过滤管，拔出过滤管；抠开滤盖，清洗滤盖和海绵网；清理完毕后重新装回过滤管",
    "verdict": "supported",
    "evidence_index": [1],
    "reason": "[1]直接记载该维护步骤"
  },
  {
    "claim": "定期清理清水箱过滤管，避免污垢堵塞过滤管",
    "verdict": "supported",
    "evidence_index": [1],
    "reason": "[1]原文明确支持"
  },
  {
    "claim": "以上操作均来自说明书明确记载的维护与故障处理内容",
    "verdict": "uncheckable",
    "evidence_index": null,
    "reason": "元评论/引用格式标注，非独立事实论断"
  },
  {
    "claim": "其他未在片段中说明的水箱内部结构、电子阀、水泵或管路检测等，资料未涉及，不予推断",
    "verdict": "uncheckable",
    "evidence_index": null,
    "reason": "免责兜底话术，'不予推断'非可核查事实"
  }
]}

{
  "claims": [
    {
      "claim": "针对RC-S200无法回充、找不到充电座的问题，按顺序执行以下步骤，任一步骤解决后即可结束排查",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段第9页明确该排查适用问题为RC-S200无法回充/找不到充电座，并说明按顺序执行、任一步骤解决后即可结束。"
    },
    {
      "claim": "步骤1：确认基站电源指示灯亮起，基站靠墙放置，前方1.5米、两侧0.5米内无障碍物和强反光物体",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段步骤1原文完全一致。"
    },
    {
      "claim": "步骤2：关机后用干燥软布轻擦主机充电极片与基站弹片，去除灰尘和毛发，不要使用湿布或金属工具；平台禁止用金属工具刮擦或短接触点",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段步骤2及安全提示原文一致。"
    },
    {
      "claim": "步骤3：移开基站前方的地毯边缘、拖鞋和数据线等杂物，确保机器人能从任意方向接近基站",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段步骤3原文完全一致。"
    },
    {
      "claim": "步骤4：把机器人放到基站前约1米处，按机身回充键重试",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段步骤4前半句原文完全一致。"
    },
    {
      "claim": "仍失败请结束自助排查并联系售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于'请联系售后'类兜底话术，不构成需证据的事实性论断。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于'请联系售后'类兜底话术，不构成需证据的事实性论断。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "针对“机器人总是被困，被电线缠住”问题，适用资料片段[1]。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "引用格式标注，非事实性论断。"
    },
    {
      "claim": "按顺序执行以下步骤，任一步骤解决后即可结束排查。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文写明“按顺序执行以下步骤，任一步骤解决后即可结束排查”。"
    },
    {
      "claim": "步骤1：清理地面数据线、充电线和窗帘绳。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1原文为“清理地面数据线、充电线和窗帘绳”。"
    },
    {
      "claim": "机器容易被线缆缠绕导致被困。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1解释“机器容易被线缆缠绕导致被困”。"
    },
    {
      "claim": "步骤2：RC-S200 最大越障高度约 18 毫米。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2明确写出“最大越障高度约 18 毫米”。"
    },
    {
      "claim": "超过 18 毫米的门槛请设置虚拟墙或垫斜坡。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2原文“超过的门槛请设置虚拟墙或垫斜坡”。"
    },
    {
      "claim": "步骤3：用干布擦拭机身底部的悬崖传感器。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3原文“用干布擦拭机身底部的悬崖传感器”。"
    },
    {
      "claim": "传感器脏污会导致机器在深色地面误判被困。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3原文“传感器脏污会导致机器在深色地面误判被困”。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于“请联系售后”类兜底话术，非事实性论断。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "RC-S200 型号出现错误码 E01（驱动轮异常）",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]标题明确给出该错误码及适用型号。"
    },
    {
      "claim": "按顺序执行以下步骤",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]原文明确'按顺序执行以下步骤'。"
    },
    {
      "claim": "步骤1（关机检查驱动轮）：关机后按压两侧驱动轮，确认能正常回弹，清理轮轴处缠绕的毛发",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]步骤1内容完全一致。"
    },
    {
      "claim": "步骤2（清除卡阻异物）：检查驱动轮与机身缝隙是否卡入石子或玩具零件并取出",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]步骤2内容完全一致。"
    },
    {
      "claim": "步骤3（重启验证）：重新开机在平整地面试运行",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]步骤3包含'重新开机在平整地面试运行'。"
    },
    {
      "claim": "E01 仍出现说明轮组内部故障",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]明确'E01 仍出现说明轮组内部故障'。"
    },
    {
      "claim": "请联系售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "'请联系售后'类兜底话术，非事实内容。"
    },
    {
      "claim": "安全提示：驱动轮电机不可自行拆解维修",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]安全提示原文一致。"
    },
    {
      "claim": "错误码 E01 的成因描述为驱动轮被卡住或悬空打滑",
      "verdict": "supported",
      "evidence_index": [2],
      "reason": "片段[2]定义错误码E01为'驱动轮被卡住或悬空打滑'。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "包含'联系官方售后'兜底话术，非事实性指令。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "RC-S200 续航变短、一次扫不完就没电的问题，适用资料片段[1]中的“RC-S200 续航变短排查”",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]标题即为“RC-S200 续航变短排查”，常见表现包括“一次扫不完就没电”。"
    },
    {
      "claim": "步骤1：在 App 查看是否长期使用最高吸力档，高档位与地毯环境耗电明显加快，改用标准档对比一次续航",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1内容完全一致。"
    },
    {
      "claim": "步骤2：让机器清扫至自动回充，然后一次性充到指示灯显示充满，重复一轮以校准电量显示",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2内容完全一致。"
    },
    {
      "claim": "步骤3：触点脏污会导致未充满即中断，关机后用干燥软布轻擦主机极片与基站弹片",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3内容完全一致。"
    },
    {
      "claim": "禁止使用湿布或金属工具接触触点",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3安全提示明确写出。"
    },
    {
      "claim": "步骤4：使用超过两年且校准后续航仍明显缩短的，属电池自然衰减，应结束自助排查并联系售后",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤4内容完全一致。"
    },
    {
      "claim": "电池不可自行拆卸或更换，必须由官方售后处理",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤4安全提示明确写出。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在，请停止自助排查并联系官方售后",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]最后一句与此完全一致。"
    }
  ]
}

